const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await ee.data.authenticateViaPrivateKey(privateKey);
  await ee.initialize();

  // 1. Geometry & Time Definitions
  const targetDate = '2025-08-03';
  const endDate = '2025-08-04'; // To ensure we capture the full day

  // Define Saskatchewan geometry
  const canada = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM0_NAME', 'Canada'));
  const saskatchewan = canada.filter(ee.Filter.eq('ADM1_NAME', 'Saskatchewan'));

  if (saskatchewan.size().getInfo() === 0) {
    console.log("Error: Could not find Saskatchewan geometry.");
    console.log("D"); // Incorrect geometry or method error
    return;
  }
  const geom = saskatchewan.geometry();

  // 2. Data Acquisition & Check
  // MODIS Thermal Anomalies / Fire Daily (MCD14ML)
  // Confidence levels: 0-30 (low), 31-64 (nominal), 65-100 (high)
  // We'll filter for nominal to high confidence (>=31).
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
    .filterDate(targetDate, endDate)
    .filterBounds(geom)
    .filter(ee.Filter.gte('confidence', 31)); // Filter for nominal/high confidence fires

  const initialCount = fireCollection.size().getInfo();

  if (initialCount === 0) {
    // Check if the reason for 0 images is the future date
    const today = new Date();
    const targetDateObj = new Date(targetDate);

    if (targetDateObj > today) {
      console.log(`No data found for future date ${targetDate}.`);
      console.log("C1"); // Empty Collection due to future date
    } else {
      console.log(`No fires detected for ${targetDate} after filtering.`);
      console.log("B"); // Valid zero, meaning no fires were detected
    }
    return;
  }

  // 3. Processing & Calculation
  // Since MCD14ML provides points, we just need to count them.
  // The 'initialCount' already gives us the number of points after filtering.

  // The question asks "were there more than 120 fires".
  const threshold = 120;
  const moreThanThreshold = initialCount > threshold;

  // 4. Validation & Final Answer
  console.log(`Fires detected on ${targetDate} in Saskatchewan: ${initialCount}`);
  console.log(`Question: More than ${threshold} fires? ${moreThanThreshold ? 'Yes' : 'No'}`);

  if (moreThanThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

// Execute the analysis
runAnalysis().catch(err => {
  console.log("An error occurred:", err);
  console.log("D"); // Catch any unexpected errors
});
